  ('a264529e-399a-5c3c-9837-923bff8dbd29', null, (select id from public.skills where slug = 'read-g5-evidence-inference'), null, 'easy',
   $q$According to the passage, what is the job of the anchorages?$q$, $q$[{"text":"They keep the ends of the main cables from pulling loose.","is_correct":true},{"text":"They hold up the middle of the road deck over the water.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"They connect the thin suspenders to the bottom of the road.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"They let air flow smoothly around the road during storms.","is_correct":false,"misconception_token":"misreads-detail"}]$q$::jsonb, $q$They keep the ends of the main cables from pulling loose.$q$, $q$Paragraph 2 says the anchorages "keep the cables from pulling loose." Letting air flow around the bridge is the job of the deck's shape, not the anchorages.$q$, 'draft', '290c9b49-2cf4-5706-8df6-56df663afd45')
